<div class="d-flex flex-wrap justify-content-between gap-2 mb-4"><div><h1>Winter Sowing Planner</h1><p class="text-muted mb-0">Eligibility comes only from explicit winter-sowing research fields. Research population is intentionally pending.</p></div></div>
<nav class="d-flex flex-wrap gap-2 mb-4" aria-label="Winter sowing month"><?php foreach(winter_sowing_month_choices() as $number=>$name):?><a class="btn <?=$month===$number?'btn-success':'btn-outline-success'?>" <?=$month===$number?'aria-current="page"':''?> href="<?=e(url('winter-sowing?month='.$number))?>"><?=e($name)?></a><?php endforeach?></nav>
<section class="mb-4"><h2 class="h4"><?=e(winter_sowing_month_choices()[$month])?> Eligible Seeds</h2><?php if(!$eligible):?><div class="alert alert-info">No seeds are confirmed eligible for this month. Unknown or unresearched seeds are never treated as suitable.</div><?php else:?><div class="row g-3"><?php foreach($eligible as $seed):?><div class="col-md-6 col-xl-4"><article class="card h-100"><div class="card-body"><h3 class="h5"><?=e($seed['name'])?><?=($seed['variety']??'')!==''?' — '.e($seed['variety']):''?></h3><dl><dt>Cold stratification</dt><dd><?=e($seed['cold_stratification'])?></dd><dt>Hardiness</dt><dd><?=e($seed['winter_hardiness'])?></dd><dt>Research citation</dt><dd><?=e($seed['winter_sowing_citation']?:'Not recorded')?></dd></dl><a class="btn btn-success" href="<?=e(url('garden/create?'.http_build_query(['seed_id'=>$seed['id'],'method'=>'Winter Sown','month'=>$month])))?>">Create Winter Sown Planting</a></div></article></div><?php endforeach?></div><?php endif?></section>
<section><h2 class="h4">Structured Research Fields</h2><p class="text-muted"><?=count($unresearched)?> seed(s) remain unknown/unresearched. Saving research here does not infer from ordinary planting data.</p><div class="accordion" id="winter-research"><?php foreach($seeds as $seed):$fieldId='winter-field-'.$seed['id'].'-'?><div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#winter-seed-<?=e($seed['id'])?>"><?=e($seed['seed_number'].' · '.$seed['name'])?> <span class="badge text-bg-light ms-2"><?=e($seed['winter_sowing_suitability'])?></span></button></h3><div id="winter-seed-<?=e($seed['id'])?>" class="accordion-collapse collapse" data-bs-parent="#winter-research"><div class="accordion-body"><form method="post" action="<?=e(url('winter-sowing/'.$seed['id'].'/research'))?>"><?=csrf_field()?><input type="hidden" name="return_month" value="<?=e($month)?>"><div class="row g-3"><div class="col-md-4"><label class="form-label" for="<?=e($fieldId.'suitability')?>">Suitability</label><select id="<?=e($fieldId.'suitability')?>" class="form-select" name="winter_sowing_suitability"><?php foreach(winter_suitabilities() as $choice):?><option <?=($seed['winter_sowing_suitability']??'Unknown')===$choice?'selected':''?>><?=e($choice)?></option><?php endforeach?></select></div><div class="col-md-4"><label class="form-label" for="<?=e($fieldId.'stratification')?>">Cold stratification</label><select id="<?=e($fieldId.'stratification')?>" class="form-select" name="cold_stratification"><?php foreach(winter_stratification_choices() as $choice):?><option <?=($seed['cold_stratification']??'Unknown')===$choice?'selected':''?>><?=e($choice)?></option><?php endforeach?></select></div><div class="col-md-4"><label class="form-label" for="<?=e($fieldId.'hardiness')?>">Hardy / tender</label><select id="<?=e($fieldId.'hardiness')?>" class="form-select" name="winter_hardiness"><?php foreach(winter_hardiness_choices() as $choice):?><option <?=($seed['winter_hardiness']??'Unknown')===$choice?'selected':''?>><?=e($choice)?></option><?php endforeach?></select></div><fieldset class="col-12"><legend class="form-label">Explicit eligible months</legend><?php foreach(winter_sowing_month_choices() as $number=>$name):?><div class="form-check form-check-inline"><input id="winter-<?=$seed['id']?>-<?=$number?>" class="form-check-input" type="checkbox" name="winter_sowing_months[]" value="<?=$number?>" <?=in_array($number,array_map('intval',explode(',',(string)$seed['winter_sowing_months'])),true)?'checked':''?>><label class="form-check-label" for="winter-<?=$seed['id']?>-<?=$number?>"><?=e($name)?></label></div><?php endforeach?></fieldset><div class="col-md-6"><label class="form-label" for="<?=e($fieldId.'notes')?>">Winter-sowing notes</label><textarea id="<?=e($fieldId.'notes')?>" class="form-control" maxlength="10000" name="winter_sowing_notes"><?=e($seed['winter_sowing_notes'])?></textarea></div><div class="col-md-6"><label class="form-label" for="<?=e($fieldId.'citation')?>">Source / research citation text</label><textarea id="<?=e($fieldId.'citation')?>" class="form-control" maxlength="10000" name="winter_sowing_citation"><?=e($seed['winter_sowing_citation'])?></textarea></div><div class="col-12"><button class="btn btn-outline-success">Save Research Fields</button></div></div></form></div></div></div><?php endforeach?></div></section>
